}

register.text:
func (c *Controller) Register(ctx context.Context, r Registration) (Receipt, error) {
	id := entityid.Derive("host", r.Cell, r.Node)
	if r.ID != "" && r.ID != id {
		return Receipt{}, errors.New("host ID differs from its node identity")
	}
	r.ID = id
	if err := validateRegistration(r, c.cell); err != nil {
		return Receipt{}, err
	}
	if r.ManagedOCI != nil && r.ManagedPlacement == nil {
		return Receipt{}, errors.New("managed host registration requires current schema-3 placement pins")
	}
	authorityEpoch := c.authorityEpoch()
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return Receipt{}, err
	}
	if r.ManagedMember != nil {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil {
			return Receipt{}, errors.New("managed host registration requires a terminal effect gate and placement scope")
		}
		release, err := c.managedEffectGate(ctx, authorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	c.registrationMu.Lock()
	defer c.registrationMu.Unlock()
	payload, operationID, err := mutationPayload(r)
	if err != nil {
		return Receipt{}, err
	}
	key := registrationSubjectKey(c.cell, r.Node)
	for range 8 {
		if r.ManagedMember != nil {
			if c.managedVerifier == nil {
				return Receipt{}, errors.New("managed host registration requires a current placement verifier")
			}
			if err := c.managedVerifier.VerifyManagedRegistration(ctx, r); err != nil {
				return Receipt{}, fmt.Errorf("verify managed host registration: %w", err)
			}
			if err := c.requireExclusiveManagedMember(ctx, r); err != nil {
				return Receipt{}, err
			}
		}
		current, revision, exists, err := c.readRegistration(ctx, r.Node)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedOCI == nil) != (r.ManagedOCI == nil) ||
				current.ManagedOCI != nil && (current.ManagedMember == nil || *current.ManagedOCI != *r.ManagedOCI ||
					*current.ManagedMember != *r.ManagedMember || current.FailureDomain != r.FailureDomain) {
				return Receipt{}, errors.New("host managed binding cannot be retargeted")
			}
			if r.Generation < current.Generation {
				return Receipt{}, errors.New("registration generation moved backward")
			}
			if r.Generation == current.Generation {
				if !sameJSON(r, current) {
					return Receipt{}, errors.New("registration changed without a generation increase")
				}
				return Receipt{r.Generation, revision}, nil
			}
		}
		if err := c.guard(ctx, authorityEpoch); err != nil {
			return Receipt{}, err
		}
		written, err := c.mutations.CommitHostMutation(ctx, authorityEpoch, authority.MutationRegistration, key, operationID, revision, payload)
		if err == nil {
			return Receipt{r.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("registration contention")
}

func (c *Controller) requireExclusiveManagedMember(ctx context.Context, candidate Registration) error {
	if c.controlLog == nil {
		return errors.New("managed member exclusivity requires ordered control log")
	}
	prefix := protocol.Control(c.cell, "host", "registration", c.cell) + "."
	info, err := c.controlLogSubjects(ctx, prefix+"*")
	if err != nil {
		return err
	}
	for subject := range info.State.Subjects {
		node, ok := strings.CutPrefix(subject, prefix)
		if !ok || validateToken(node, "node") != nil {
			return errors.New("managed member registration subject is invalid")
		}
		if node == candidate.Node {
			continue
		}
		other, _, exists, err := c.readRegistration(ctx, node)
		if err != nil {
			return err
		}
		if exists && other.ManagedMember != nil && sameLogicalMember(other.ManagedMember.Scope, candidate.ManagedMember.Scope) {
			// A replacement host carries the next host attempt of the same
			// logical member. The verifier has already bound the candidate to
			// the seat's current durable attempt, which the placement
			// controller only advances through its fenced, evidence-gated
			// replacement once the previous host is proven lost. An older
			// attempt's registration therefore no longer owns the member;
			// an equal or newer one still does.
			if other.ManagedMember.HostAttempt < candidate.ManagedMember.HostAttempt {
				continue
			}
			return errors.New("managed member is already bound to another host")
		}
	}
	return nil
}

func sameLogicalMember(a, b MemberScope) bool {
	return a.ClusterID == b.ClusterID && a.TenantID == b.TenantID && a.DatabaseID == b.DatabaseID &&
		a.ShardID == b.ShardID && a.MemberID == b.MemberID
}

subject_inventory.text:
// controlLogSubjects reads the control log's state for the subjects matching
// filter. jetstream's Stream.Info caches its reply in the shared handle
// without a lock; Info and history GetMsg calls share this lock because
// GetMsg reads that cached configuration too.
func (c *Controller) controlLogSubjects(ctx context.Context, filter string) (*jetstream.StreamInfo, error) {
	if err := c.lockControlLog(ctx); err != nil {
		return nil, err
	}
	defer func() { <-c.controlLogInfoGate }()
	return c.controlLog.Info(ctx, jetstream.WithSubjectFilter(filter))
}

func (c *Controller) lockControlLog(ctx context.Context) error {
	c.controlLogInfoOnce.Do(func() { c.controlLogInfoGate = make(chan struct{}, 1) })
	if err := ctx.Err(); err != nil {
		return err
	}
	select {
	case c.controlLogInfoGate <- struct{}{}:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

mutation_reads.text:
func (c *Controller) readRegistration(ctx context.Context, node string) (Registration, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Registration{}, 0, false, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRegistration, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Registration{}, 0, false, nil
	}
	if err != nil {
		return Registration{}, 0, false, err
	}
	if entry.Kind != authority.MutationRegistration || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Registration{}, 0, false, errors.New("registration log entry is malformed")
	}
	var r Registration
	if err := decodeStrict(entry.Payload, &r); err != nil {
		return Registration{}, 0, false, err
	}
	if r.Node != node || r.ID != entityid.Derive("host", c.cell, node) {
		return Registration{}, 0, false, errors.New("registration log identity mismatch")
	}
	if err := validateRegistration(r, c.cell); err != nil {
		return Registration{}, 0, false, err
	}
	return r, entry.Sequence, true, nil
}

func (c *Controller) readDesired(ctx context.Context, node, role string) (Desired, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Desired{}, 0, false, err
	}
	if err := validateToken(role, "role"); err != nil {
		return Desired{}, 0, false, err
	}
	key := desiredSubjectKey(c.cell, node, role)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationDesired, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Desired{}, 0, false, nil
	}
	if err != nil {
		return Desired{}, 0, false, err
	}
	if entry.Kind != authority.MutationDesired || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Desired{}, 0, false, errors.New("desired log entry is malformed")
	}
	var d Desired
	if err := decodeStrict(entry.Payload, &d); err != nil {
		return Desired{}, 0, false, err
	}
	if d.Cell != c.cell || d.Node != node || d.Role != role || d.AuthorityEpoch != entry.Epoch {
		return Desired{}, 0, false, errors.New("desired log identity or epoch mismatch")
	}
	return d, entry.Sequence, true, nil

obsolete_keys.text:
func rejectObsoleteRetirementState(ctx context.Context, state jetstream.KeyValue, cell string) error {
	keys, err := state.ListKeysFiltered(ctx, "retired."+cell+".>", "retirement-quarantine."+cell+".>", "retirement-cutover."+cell)
	if err != nil {
		return fmt.Errorf("validate host retirement storage: %w", err)
	}
	defer keys.Stop()
	obsolete := false
	for range keys.Keys() {
		obsolete = true
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if obsolete {
		return errors.New("host state contains obsolete retirement keys; updated host control cannot start over this state")
	}
	return nil
}

retirement_decode.text:
func (c *Controller) readRetirement(ctx context.Context, node string) (retirement, uint64, error) {
	if err := validateToken(node, "node"); err != nil {
		return retirement{}, 0, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRetirement, key)
	if errors.Is(err, authority.ErrNotFound) {
		return retirement{}, 0, nil
	}
	if err != nil {
		return retirement{}, 0, err
	}
	if entry.Kind != authority.MutationRetirement || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return retirement{}, 0, errors.New("retirement log entry is malformed")
	}
	mark, err := decodeRetirement(entry.Payload)
	if err != nil {
		return retirement{}, 0, err
	}
	return mark, entry.Sequence, nil
}

func decodeRetirement(payload []byte) (retirement, error) {
	var value struct {
		Retired *bool `json:"retired"`
	}
	if err := decodeStrict(payload, &value); err != nil {
		return retirement{}, err
	}
	if value.Retired == nil {
		return retirement{}, errors.New("retirement record requires a non-null retired state")
	}
	return retirement{Retired: *value.Retired}, nil
}

retirement_operations.text:
// retirement is a node's retirement state in the ordered control log.
type retirement struct {
	Retired bool `json:"retired"`
}

func (c *Controller) retired(ctx context.Context, node string) (bool, error) {
	mark, _, err := c.readRetirement(ctx, node)
	return mark.Retired, err
}

func (c *Controller) markRetired(ctx context.Context, epoch uint64, node string, retired bool) error {
	if err := c.guard(ctx, epoch); err != nil {
		return err
	}
	data, operation, err := mutationPayload(retirement{Retired: retired})
	if err != nil {
		return err
	}
	for range 8 {
		mark, revision, err := c.readRetirement(ctx, node)
		if err != nil {
			return err
		}
		if mark.Retired == retired {
			return nil
		}
		_, err = c.mutations.CommitHostMutation(ctx, epoch, authority.MutationRetirement, registrationSubjectKey(c.cell, node), operation, revision, data)
		if err == nil {
			return nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return fmt.Errorf("mark %s retired=%t: %w", node, retired, err)
		}
	}
	return errors.New("host retirement contention")
}

// RetireIdle retires node if it holds no active allocation and reports
// whether it did. A retired node takes no new allocation until Unretire,
// also from a later leader: the mark is in the log and every desired
// commit reads it. Withdrawals still apply. The process lock excludes desired
// commits during the idle check; the captured epoch fences leadership changes.
func (c *Controller) RetireIdle(ctx context.Context, node string) (bool, error) {
	c.retireMu.Lock()
	defer c.retireMu.Unlock()
	epoch := c.authorityEpoch()
	if err := c.guard(ctx, epoch); err != nil {
		return false, err
	}
	desired, err := c.ListDesired(ctx, "")
	if err != nil {
		return false, err
	}
	for _, d := range desired {
		if d.Node == node && !d.Withdrawn {
			return false, nil
		}
	}
	if err := c.markRetired(ctx, epoch, node, true); err != nil {
		return false, err
	}
	return true, nil
}

// Unretire lets node take allocations again: a new host under a retired
// host's name.
func (c *Controller) Unretire(ctx context.Context, node string) error {
	c.retireMu.Lock()
	defer c.retireMu.Unlock()
	return c.markRetired(ctx, c.authorityEpoch(), node, false)
}

usage_history.text:
func (c *Controller) InitializeUsageHistory(ctx context.Context) error {
	if err := c.lockControlLog(ctx); err != nil {
		return err
	}
	defer func() { <-c.controlLogInfoGate }()
	info, err := c.controlLog.Info(ctx, jetstream.WithSubjectFilter(protocol.Control(c.cell, "host")+".>"))
	if err != nil {
		return err
	}
	if err := c.usageHistory.Seed(ctx, c.controlLog, c.cell, info); err != nil {
		return err
	}
	return c.usageHistory.Advance(ctx, c.controlLog, c.cell, info.State.LastSeq)
}

// ExpectedUsage reads timestamped admission, allocation and retirement history
// without letting later changes rewrite an earlier window's expectations.
func (c *Controller) ExpectedUsage(ctx context.Context, from, to time.Time) ([]hostload.UsageInterval, error) {
	if c == nil || c.controlLog == nil || !from.Before(to) {
		return nil, errors.New("historical host inventory is unavailable")
	}
	if err := c.lockControlLog(ctx); err != nil {
		return nil, err
	}
	defer func() { <-c.controlLogInfoGate }()
	info, err := c.controlLog.Info(ctx)
	if err != nil {
		return nil, err
	}
	expected := []hostload.UsageInterval{}
	entries, err := c.usageHistory.Window(ctx, c.controlLog, c.cell, from, to, info.State.LastSeq)
	if err != nil {
		return nil, err
	}
	active, err := c.activeUsageIntervals(entries, from, to)
	if err != nil {
		return nil, err
	}
	ends := map[string]time.Time{}
	for _, entry := range slices.Backward(entries) {
		if entry.Kind == authority.MutationRetirement || entry.Kind == authority.MutationUsageObservation {
			continue
		}
		key := string(entry.Kind) + "/" + entry.SubjectKey
		end, ok := ends[key]
		if !ok {
			end = to
		}
		ends[key] = entry.CreatedAt
		if !end.After(from) || !entry.CreatedAt.Before(end) {
			continue
		}
		if entry.Kind == authority.MutationRegistration {
			var registration Registration
			if err := decodeStrict(entry.Payload, &registration); err != nil {
				return nil, err
			}
			if entry.SubjectKey != registrationSubjectKey(c.cell, registration.Node) || registration.ID != entityid.Derive("host", c.cell, registration.Node) {
				return nil, errors.New("historical registration identity mismatch")
			}
			if err := validateRegistration(registration, c.cell); err != nil {
				return nil, err
			}
			for _, interval := range intersectActiveUsage(active, registrationSubjectKey(c.cell, registration.Node), laterTime(from, entry.CreatedAt), end) {
				expected = append(expected, hostload.UsageInterval{Node: registration.Node, Environment: registration.Environment, From: interval.from, To: interval.to})
			}
		} else {
			var desired Desired
			if err := decodeStrict(entry.Payload, &desired); err != nil {
				return nil, err
			}
			if desired.Cell != c.cell || desired.AuthorityEpoch != entry.Epoch ||
				entry.SubjectKey != desiredSubjectKey(c.cell, desired.Node, desired.Role) {
				return nil, errors.New("historical desired identity or epoch mismatch")
			}
			if !desired.Withdrawn {
				for _, interval := range intersectActiveUsage(active, registrationSubjectKey(c.cell, desired.Node), laterTime(from, entry.CreatedAt), end) {
					expected = append(expected, hostload.UsageInterval{Node: desired.Node, Environment: desired.Environment, Role: desired.Role, From: interval.from, To: interval.to})
				}
			}
		}
	}
	slices.SortFunc(expected, func(a, b hostload.UsageInterval) int {
		if order := strings.Compare(a.Node+"/"+a.Environment+"/"+a.Role, b.Node+"/"+b.Environment+"/"+b.Role); order != 0 {
			return order
		}
		return a.From.Compare(b.From)
	})
	merged := expected[:0]
	for _, interval := range expected {
		if len(merged) > 0 {
			last := &merged[len(merged)-1]
			if last.Node == interval.Node && last.Environment == interval.Environment && last.Role == interval.Role && !last.To.Before(interval.From) {
				last.To = laterTime(last.To, interval.To)
				continue
			}
		}
		merged = append(merged, interval)
	}
	return merged, nil
}

usage_arithmetic.text:
type usageInterval struct{ from, to time.Time }

func laterTime(a, b time.Time) time.Time {
	if b.After(a) {
		return b
	}
	return a
}

func (c *Controller) activeUsageIntervals(entries []authority.LogEntry, from, to time.Time) (map[string][]usageInterval, error) {
	active := map[string][]usageInterval{}
	retired := map[string]bool{}
	cursor := map[string]time.Time{}
	for _, entry := range entries {
		if entry.Kind != authority.MutationRetirement {
			continue
		}
		node, ok := strings.CutPrefix(entry.SubjectKey, c.cell+".")
		if !ok || validateToken(node, "node") != nil {
			return nil, errors.New("historical retirement identity mismatch")
		}
		mark, err := decodeRetirement(entry.Payload)
		if err != nil {
			return nil, err
		}
		start := cursor[entry.SubjectKey]
		if start.IsZero() {
			start = from
			active[entry.SubjectKey] = nil
		}
		if !retired[entry.SubjectKey] && start.Before(entry.CreatedAt) {
			active[entry.SubjectKey] = append(active[entry.SubjectKey], usageInterval{start, entry.CreatedAt})
		}
		retired[entry.SubjectKey] = mark.Retired
		cursor[entry.SubjectKey] = laterTime(from, entry.CreatedAt)
	}
	for key, state := range retired {
		if !state && cursor[key].Before(to) {
			active[key] = append(active[key], usageInterval{cursor[key], to})
		}
	}
	return active, nil
}

func intersectActiveUsage(active map[string][]usageInterval, key string, from, to time.Time) []usageInterval {
	if !from.Before(to) {
		return nil
	}
	intervals, known := active[key]
	if !known {
		return []usageInterval{{from, to}}
	}
	i := sort.Search(len(intervals), func(i int) bool { return intervals[i].to.After(from) })
	var overlap []usageInterval
	for ; i < len(intervals) && intervals[i].from.Before(to); i++ {
		end := to
		if intervals[i].to.Before(end) {
			end = intervals[i].to
		}
		overlap = append(overlap, usageInterval{laterTime(from, intervals[i].from), end})
	}
	return overlap
}

history_store.text:
func (h *HostHistory) Seed(ctx context.Context, stream jetstream.Stream, scope string, info *jetstream.StreamInfo) error {
	if err := h.lock(ctx); err != nil {
		return err
	}
	defer func() { <-h.gate }()
	if !h.since.IsZero() && time.Since(h.updated) < time.Hour {
		return nil
	}
	baseline := map[string]LogEntry{}
	var newest time.Time
	for _, subject := range slices.Sorted(maps.Keys(info.State.Subjects)) {
		if !strings.HasPrefix(subject, mutationSubject(scope, MutationRegistration, scope+".")) && !strings.HasPrefix(subject, mutationSubject(scope, MutationDesired, scope+".")) && !strings.HasPrefix(subject, mutationSubject(scope, MutationRetirement, scope+".")) {
			continue
		}
		entry, err := stream.GetLastMsgForSubject(ctx, subject)
		if err != nil {
			return err
		}
		value, err := decodeHostHistoryEntry(entry, scope)
		if err != nil || entry.Subject != subject {
			return errors.Join(err, errors.New("host history baseline identity is invalid"))
		}
		if value.Kind == MutationUsageObservation {
			continue
		}
		baseline[subject] = value
		if entry.Time.After(newest) {
			newest = entry.Time
		}
		if len(baseline) > hostHistoryLimit {
			return errors.New("host history exceeds inventory bound")
		}
	}
	h.baseline, h.next = baseline, info.State.LastSeq+1
	h.changes = nil
	h.since = time.Now().UTC()
	h.updated = h.since
	if newest.After(h.since) {
		h.since = newest
	}
	return nil
}

// Window advances the checkpoint only through watermark, then reads the cache.
func (h *HostHistory) Window(ctx context.Context, stream jetstream.Stream, scope string, from, to time.Time, watermark uint64) ([]LogEntry, error) {
	if err := h.lock(ctx); err != nil {
		return nil, err
	}
	defer func() { <-h.gate }()
	if h.since.IsZero() || time.Since(h.updated) >= time.Hour || from.Before(h.since) || !from.Before(to) {
		return nil, errors.New("inventory window predates the cached baseline")
	}
	if err := h.advance(ctx, stream, scope, watermark); err != nil {
		return nil, err
	}
	if from.Before(h.since) {
		return nil, errors.New("inventory window has expired")
	}
	baseline := maps.Clone(h.baseline)
	for _, entry := range baseline {
		if entry.Sequence > watermark {
			return nil, errors.New("inventory baseline exceeds the selected watermark")
		}
	}
	var result []LogEntry
	for _, entry := range h.changes {
		if entry.Sequence > watermark {
			continue
		}
		if entry.CreatedAt.Before(from) {
			baseline[mutationSubject(scope, entry.Kind, entry.SubjectKey)] = entry
		} else if entry.CreatedAt.Before(to) {
			result = append(result, entry)
		}
	}
	result = append(result, slices.Collect(maps.Values(baseline))...)
	slices.SortFunc(result, func(a, b LogEntry) int { return cmp.Compare(a.Sequence, b.Sequence) })
	return result, nil
}

// Advance keeps the cache current even when there are no usage queries.
func (h *HostHistory) Advance(ctx context.Context, stream jetstream.Stream, scope string, watermark uint64) error {
	if err := h.lock(ctx); err != nil {
		return err
	}
	defer func() { <-h.gate }()
	if h.since.IsZero() {
		return errors.New("inventory baseline unavailable")
	}
	return h.advance(ctx, stream, scope, watermark)
}

func (h *HostHistory) advance(ctx context.Context, stream jetstream.Stream, scope string, watermark uint64) error {
	cutoff := time.Now().Add(-time.Hour)
	if cutoff.After(h.since) {
		kept := h.changes[:0]
		for _, entry := range h.changes {
			if entry.CreatedAt.Before(cutoff) {
				h.baseline[mutationSubject(scope, entry.Kind, entry.SubjectKey)] = entry
			} else {
				kept = append(kept, entry)
			}
		}
		clear(h.changes[len(kept):])
		h.changes, h.since = kept, cutoff
	}
	filter := protocol.Control(scope, "host") + ".>"
	for h.next <= watermark {
		entry, err := stream.GetMsg(ctx, h.next, jetstream.WithGetMsgSubject(filter))
		if errors.Is(err, jetstream.ErrMsgNotFound) || err == nil && entry.Sequence > watermark {
			h.next = watermark + 1
			break
		}
		if err != nil {
			return err
		}
		if entry.Sequence < h.next {
			return errors.New("host history sequence is invalid")
		}
		value, err := decodeHostHistoryEntry(entry, scope)
		if err != nil {
			return err
		}
		if value.Kind == MutationUsageObservation {
			h.next = entry.Sequence + 1
			continue
		}
		prior := h.baseline[entry.Subject]
		// Seed reads can overlap newer commits; never replace them with older state.
		if value.Sequence > prior.Sequence {
			if len(h.baseline)+len(h.changes) >= hostHistoryLimit && (prior.Sequence == 0 || !value.CreatedAt.Before(h.since)) {
				return errors.New("host history exceeds inventory bound")
			}
			if value.CreatedAt.Before(h.since) {
				h.baseline[entry.Subject] = value
			} else {
				h.changes = append(h.changes, value)
			}
		}
		h.next = entry.Sequence + 1
	}
	h.updated = time.Now().UTC()
	return nil
}

history_decode.text:
func decodeHostHistoryEntry(entry *jetstream.RawStreamMsg, scope string) (LogEntry, error) {
	record, err := decodeControlRecord(entry.Data)
	if err != nil || entry.Sequence == 0 || entry.Time.IsZero() || record.Scope != scope || record.Epoch == 0 || entry.Subject != mutationSubject(scope, record.Kind, record.SubjectKey) || validateHostMutation(record.Kind, record.SubjectKey, record.OperationID, record.Payload) != nil {
		return LogEntry{}, errors.New("host history control entry is invalid")
	}
	return LogEntry{Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID, Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: record.Payload}, nil
}

