runner_recover.text:
func NewProcessRunner(stateRoot string, identity WorkloadIdentity, cell, node string) Runner {
	return &processRunner{root: stateRoot, cell: cell, node: node, identity: identity, closing: make(chan struct{}), records: make(map[string]processRecord), commands: make(map[string]*exec.Cmd)}
}

func nativeCgroupName(stateRoot string) string {
	hash := sha256.Sum256([]byte(stateRoot))
	return "terrascale-host-" + hex.EncodeToString(hash[:8])
}

func (p *processRunner) Recover(ctx context.Context) error {
	if p.root == "" || !filepath.IsAbs(p.root) {
		return errors.New("native runner requires absolute state root")
	}
	if err := validateWorkloadIdentity(p.identity); err != nil {
		return err
	}
	root, err := nativeCgroupRoot(p.root)
	if err != nil {
		return err
	}
	p.cgroups = root
	if err := os.MkdirAll(p.root, 0700); err != nil {
		return err
	}
	if err := validatePrivateStateRoot(p.root); err != nil {
		return err
	}
	lock, err := os.OpenFile(filepath.Join(p.root, "owner.lock"), os.O_CREATE|os.O_RDWR, 0600)
	if err != nil {
		return err
	}
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		lock.Close()
		return fmt.Errorf("host is already owned: %w", err)
	}
	p.mu.Lock()
	if p.lock != nil {
		p.mu.Unlock()
		lock.Close()
		return errors.New("runner already recovered")
	}
	p.lock = lock
	p.mu.Unlock()
	if err := prepareNativeCgroupRoot(p.cgroups); err != nil {
		return err
	}
	if err := configureTenantCgroupDirectory(p.cgroups, p.identity); err != nil {
		return fmt.Errorf("configure native runner cgroup traversal: %w", err)
	}
	if err := validateTenantCgroupTraversal(p.cgroups, p.identity); err != nil {
		return err
	}
	for _, name := range []string{"cgroup.procs", "cgroup.subtree_control"} {
		if err := validateTenantCgroupControl(filepath.Join(p.cgroups, name), p.identity); err != nil {
			return err
		}
	}
	entries, err := os.ReadDir(p.cgroups)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		if err := validateToken(entry.Name(), "cgroup role"); err != nil {
			return err
		}
		if err := terminateCgroup(ctx, filepath.Join(p.cgroups, entry.Name())); err != nil {
			return fmt.Errorf("recover native cgroup %s: %w", entry.Name(), err)
		}
		if err := os.WriteFile(filepath.Join(p.cgroups, entry.Name(), "cgroup.freeze"), []byte("0"), 0600); err != nil {
			return fmt.Errorf("unfreeze recovered native cgroup %s: %w", entry.Name(), err)
		}
	}
	data, err := os.ReadFile(filepath.Join(p.root, "inventory.json"))
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	var records []processRecord
	if err := decodeStrict(data, &records); err != nil {
		return fmt.Errorf("invalid native inventory: %w", err)
	}
	if len(records) > 32 {
		return errors.New("native inventory exceeds role limit")
	}
	for _, record := range records {
		if err := validateToken(record.Role, "inventory role"); err != nil {
			return err
		}
		if err := validateDigest(record.Digest); err != nil {
			return err
		}
		if record.PID < 2 || record.StartTime == "" {
			return errors.New("invalid native inventory process")
		}
		// The cgroup scan above kills descendants even if the recorded leader exited.
	}
	return p.persist()
}

runner_apply.text:
func (p *processRunner) Apply(ctx context.Context, w Workload) error {
	if err := validateToken(w.Role, "role"); err != nil {
		return err
	}
	if err := validateDigest(w.Digest); err != nil {
		return err
	}
	if err := validateDigest(w.Fingerprint); err != nil {
		return fmt.Errorf("invalid workload fingerprint: %w", err)
	}
	if err := validateCgroupMemoryMax(w.CgroupMemoryMaxBytes); err != nil {
		return err
	}
	if !filepath.IsAbs(w.Executable) {
		return errors.New("workload executable must be absolute")
	}
	if err := validateTenantExecutable(w.Executable, p.identity); err != nil {
		return err
	}
	if err := p.Stop(ctx, w.Role); err != nil {
		return err
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.lock == nil {
		return errors.New("runner is not recovered")
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if runnerClosing(p.closing) {
		return errors.New("runner is closing")
	}
	if w.SystemReserveBytes != 0 {
		if err := validateNativeSupervisorReservation(filepath.Dir(p.cgroups), p.cgroups, w.SystemReserveBytes); err != nil {
			return fmt.Errorf("validate managed supervisor reservation: %w", err)
		}
	}
	cgroupPath := filepath.Join(p.cgroups, w.Role)
	// Linux 6.1.155 can compare the host's kill sequence to the target's
	// incremented sequence after cgroup.kill, killing a clone3 child before exec.
	if err := removeEmptyCgroupTree(cgroupPath); err != nil {
		return fmt.Errorf("reset workload cgroup: %w", err)
	}
	if w.CgroupMemoryMaxBytes != 0 {
		if err := enableCgroupMemoryController(p.cgroups); err != nil {
			return fmt.Errorf("enable workload memory controller: %w", err)
		}
	}
	if err := os.MkdirAll(cgroupPath, 0700); err != nil {
		return fmt.Errorf("create workload cgroup: %w", err)
	}
	if w.CgroupMemoryMaxBytes != 0 {
		if err := setCgroupMemoryMax(cgroupPath, w.CgroupMemoryMaxBytes); err != nil {
			return fmt.Errorf("configure workload memory cap: %w", err)
		}
	}
	quota, err := deriveNativeWorkloadCPUQuota(filepath.Dir(p.cgroups))
	if err != nil {
		return fmt.Errorf("derive workload CPU cap: %w", err)
	}
	if err := setNativeCPUMax(filepath.Join(p.cgroups, "cpu.max"), quota); err != nil {
		return fmt.Errorf("configure aggregate workload CPU cap: %w", err)
	}
	if err := configureNativeRoleResources(cgroupPath, quota); err != nil {
		return fmt.Errorf("configure workload resource isolation: %w", err)
	}
	if err := configureTenantCgroupDirectory(cgroupPath, p.identity); err != nil {
		return fmt.Errorf("configure workload cgroup traversal: %w", err)
	}
	if err := validateTenantCgroupControl(filepath.Join(cgroupPath, "cgroup.procs"), p.identity); err != nil {
		return err
	}
	if w.CgroupMemoryMaxBytes != 0 {
		if err := validateTenantCgroupAccounting(cgroupPath, p.identity); err != nil {
			return err
		}
	} else if err := validateTenantCgroupTraversal(cgroupPath, p.identity); err != nil {
		return err
	}
	cgroup, err := os.Open(cgroupPath)
	if err != nil {
		return err
	}
	defer cgroup.Close()
	if err := terminateCgroup(ctx, cgroupPath); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if runnerClosing(p.closing) {
		return errors.New("runner is closing")
	}
	target := exec.Command(w.Executable, w.Args...)
	target.Stdout = os.Stdout
	target.Stderr = os.Stderr
	environment := map[string]string{"HOME": "/", "LANG": "C", "PATH": "/usr/bin:/bin"}
	for key, value := range w.Env {
		environment[key] = value
	}
	// Set last, so the workload reports the identity the agent gave it.
	environment["TS_SERVICE"] = w.Role
	environment["TS_REGION"] = p.cell
	environment["TS_NODE"] = p.node
	for key, value := range environment {
		target.Env = append(target.Env, key+"="+value)
	}
	sort.Strings(target.Env)
	watchDone := make(chan struct{})
	defer close(watchDone)
	go func() {
		select {
		case <-ctx.Done():
		case <-p.closing:
		case <-watchDone:
			if runnerApplyInterrupted(ctx, p.closing) == nil {
				return
			}
		}
		killCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = sealCgroup(killCtx, cgroupPath)
	}()
	cmd, release, waited, err := launchNativeWorkload(ctx, target, cgroup, cgroupPath, p.identity)
	if err != nil {
		return fmt.Errorf("start workload in cgroup v2: %w", err)
	}
	defer release()
	if err := runnerApplyInterrupted(ctx, p.closing); err != nil {
		if stopErr := terminateCgroup(context.Background(), cgroupPath); stopErr != nil {
			_ = cmd.Process.Kill()
		}
		release()
		<-waited
		return err
	}
	start := currentStartTime(cmd.Process.Pid)
	if start == "" {
		if err := terminateCgroup(context.Background(), cgroupPath); err != nil {
			_ = cmd.Process.Kill()
		}
		release()
		<-waited
		return errors.New("cannot identify native process")
	}
	record := processRecord{Role: w.Role, Digest: w.Digest, Fingerprint: w.Fingerprint, PID: cmd.Process.Pid, StartTime: start,
		DrainMillis: w.DrainTimeout.Milliseconds()}
	p.records[w.Role] = record
	p.commands[w.Role] = cmd
	if err := p.persistLocked(); err != nil {
		if stopErr := terminateCgroup(context.Background(), cgroupPath); stopErr != nil {
			_ = cmd.Process.Kill()
		}
		release()
		<-waited
		delete(p.records, w.Role)
		delete(p.commands, w.Role)
		return err
	}
	if err := runnerApplyInterrupted(ctx, p.closing); err != nil {
		if stopErr := terminateCgroup(context.Background(), cgroupPath); stopErr != nil {
			_ = cmd.Process.Kill()
		}
		release()
		<-waited
		delete(p.records, w.Role)
		delete(p.commands, w.Role)
		return errors.Join(err, p.persistLocked())
	}
	release()
	go func() {
		level, result := slog.LevelInfo, "exit status 0"
		if err := <-waited; err != nil {
			level, result = slog.LevelWarn, err.Error()
		}
		slog.Log(ctx, level, "native workload exited", observability.ComponentKey, "host",
			"role", w.Role, "pid", record.PID, "digest", w.Digest[:12], "result", result)
	}()
	return nil
}

runner_memory.text:
func validateCgroupMemoryMax(limit uint64) error {
	if limit == 0 {
		return nil
	}
	page := uint64(os.Getpagesize())
	if limit < page || limit > math.MaxInt64 || limit%page != 0 {
		return errors.New("workload cgroup memory cap must be finite, page-aligned and fit signed 64-bit")
	}
	return nil
}

func enableCgroupMemoryController(parent string) error {
	return enableCgroupController(parent, "memory")
}

func enableCgroupCPUController(parent string) error {
	return enableCgroupController(parent, "cpu")
}

func enableCgroupIOController(parent string) error {
	return enableCgroupController(parent, "io")
}

func enableCgroupController(parent, controller string) error {
	path := filepath.Join(parent, "cgroup.subtree_control")
	file, err := os.OpenFile(path, os.O_WRONLY, 0)
	if err != nil {
		return err
	}
	if _, err := file.WriteString("+" + controller); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	readback, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if !slices.Contains(strings.Fields(string(readback)), controller) {
		return fmt.Errorf("kernel cgroup.subtree_control does not include %s: %q", controller, strings.TrimSpace(string(readback)))
	}
	return nil
}

func setCgroupMemoryMax(cgroupPath string, limit uint64) error {
	want := strconv.FormatUint(limit, 10)
	path := filepath.Join(cgroupPath, "memory.max")
	if err := os.WriteFile(path, []byte(want), 0600); err != nil {
		return err
	}
	readback, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if strings.TrimSpace(string(readback)) != want {
		return fmt.Errorf("kernel memory.max readback %q differs from requested %q", strings.TrimSpace(string(readback)), want)
	}
	return nil
}

func readCgroupMemoryMax(cgroupPath string) (uint64, error) {
	data, err := os.ReadFile(filepath.Join(cgroupPath, "memory.max"))
	if err != nil {
		return 0, err
	}
	value := strings.TrimSpace(string(data))
	if value == "max" {
		return 0, nil
	}
	limit, err := strconv.ParseUint(value, 10, 64)
	if err != nil {
		return 0, errors.New("invalid role memory.max readback")
	}
	return limit, nil
}

runner_stop_observe.text:
func (p *processRunner) Stop(ctx context.Context, role string) error {
	if err := validateToken(role, "role"); err != nil {
		return err
	}
	p.mu.Lock()
	record, exists := p.records[role]
	p.mu.Unlock()
	if exists && record.DrainMillis > 0 {
		p.drain(ctx, record)
	}
	if err := terminateCgroup(ctx, filepath.Join(p.cgroups, role)); err != nil {
		return err
	}
	if !exists {
		return nil
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.records[role] == record {
		delete(p.records, role)
		delete(p.commands, role)
		return p.persistLocked()
	}
	return nil
}

func (p *processRunner) Observe(ctx context.Context, role string) (Observation, error) {
	if err := ctx.Err(); err != nil {
		return Observation{}, err
	}
	p.mu.Lock()
	record, exists := p.records[role]
	p.mu.Unlock()
	if !exists {
		return Observation{Role: role}, nil
	}
	populated, err := cgroupPopulated(filepath.Join(p.cgroups, role))
	if err != nil {
		return Observation{}, err
	}
	running := populated && nativeProcessAliveWithStart(record.PID, record.StartTime)
	observation := Observation{Role: role, Digest: record.Digest, Fingerprint: record.Fingerprint, PID: record.PID, Running: running}
	if running {
		observation.CgroupMemoryMaxBytes, err = readCgroupMemoryMax(filepath.Join(p.cgroups, role))
		if err != nil {
			return Observation{}, err
		}
	}
	return observation, nil
}

runner_close.text:
func (p *processRunner) Close(ctx context.Context) error {
	p.closeOnce.Do(func() { close(p.closing) })
	var failures []error
	entries, err := os.ReadDir(p.cgroups)
	if err != nil {
		failures = append(failures, err)
	}
	for _, entry := range entries {
		if entry.IsDir() {
			path := filepath.Join(p.cgroups, entry.Name())
			if err := sealCgroup(ctx, path); err != nil {
				failures = append(failures, err)
			}
		}
	}
	if err := lockRunnerUntil(ctx, &p.mu); err != nil {
		return errors.Join(append(failures, err)...)
	}
	defer p.mu.Unlock()
	removed := false
	for role := range p.records {
		if err := sealCgroup(ctx, filepath.Join(p.cgroups, role)); err != nil {
			failures = append(failures, err)
			continue
		}
		delete(p.records, role)
		delete(p.commands, role)
		removed = true
	}
	if removed && p.lock != nil {
		if err := p.persistLocked(); err != nil {
			failures = append(failures, err)
		}
	}
	if len(failures) == 0 && p.lock != nil {
		_ = syscall.Flock(int(p.lock.Fd()), syscall.LOCK_UN)
		_ = p.lock.Close()
		p.lock = nil
	}
	return errors.Join(failures...)
}

// Seal the cgroup before waiting for Apply's mutex. A frozen child cannot run
// user code; removing the empty cgroup also makes a late clone3 through an
// already-open cgroup FD fail instead of blocking in a frozen child.
func sealCgroup(ctx context.Context, path string) error {
	freezeErr := os.WriteFile(filepath.Join(path, "cgroup.freeze"), []byte("1"), 0600)
	if errors.Is(freezeErr, os.ErrNotExist) {
		if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) {
			return nil
		}
	}
	ticker := time.NewTicker(25 * time.Millisecond)
	defer ticker.Stop()
	for {
		if err := terminateCgroup(ctx, path); err != nil {
			return errors.Join(freezeErr, err)
		}
		err := removeEmptyCgroupTree(path)
		if err == nil || errors.Is(err, os.ErrNotExist) {
			return nil
		}
		if !errors.Is(err, syscall.EBUSY) && !errors.Is(err, syscall.ENOTEMPTY) {
			return errors.Join(freezeErr, fmt.Errorf("remove workload cgroup: %w", err))
		}
		select {
		case <-ctx.Done():
			return errors.Join(freezeErr, fmt.Errorf("remove workload cgroup: %w", err), ctx.Err())
		case <-ticker.C:
		}
	}
}

func removeEmptyCgroupTree(path string) error {
	entries, err := os.ReadDir(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if entry.IsDir() {
			if err := removeEmptyCgroupTree(filepath.Join(path, entry.Name())); err != nil {
				return err
			}
		}
	}
	return os.Remove(path)
}

func runnerClosing(closing <-chan struct{}) bool {
	select {
	case <-closing:
		return true
	default:
		return false
	}
}

func runnerApplyInterrupted(ctx context.Context, closing <-chan struct{}) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if runnerClosing(closing) {
		return errors.New("runner is closing")
	}
	return nil
}

func lockRunnerUntil(ctx context.Context, mu *sync.Mutex) error {
	ticker := time.NewTicker(10 * time.Millisecond)
	defer ticker.Stop()
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		if mu.TryLock() {
			return nil
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

cgroup_termination.text:
func currentStartTime(pid int) string {
	data, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
	if err != nil {
		return ""
	}
	closing := strings.LastIndexByte(string(data), ')')
	if closing < 0 {
		return ""
	}
	fields := strings.Fields(string(data[closing+1:]))
	if len(fields) <= 19 {
		return ""
	}
	return fields[19]
}

func nativeProcessAliveWithStart(pid int, start string) bool {
	if start == "" {
		return false
	}
	data, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
	if err != nil {
		return false
	}
	closing := strings.LastIndexByte(string(data), ')')
	if closing < 0 {
		return false
	}
	fields := strings.Fields(string(data[closing+1:]))
	return len(fields) > 19 && fields[19] == start && fields[0] != "Z" && fields[0] != "X" && fields[0] != "x"
}

func cgroupPopulated(path string) (bool, error) {
	data, err := os.ReadFile(filepath.Join(path, "cgroup.events"))
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	for line := range strings.SplitSeq(string(data), "\n") {
		if line == "populated 0" {
			return false, nil
		}
		if line == "populated 1" {
			return true, nil
		}
	}
	return false, errors.New("cgroup.events lacks populated status")
}

func terminateCgroup(ctx context.Context, path string) error {
	populated, err := cgroupPopulated(path)
	if err != nil || !populated {
		return err
	}
	if err := os.WriteFile(filepath.Join(path, "cgroup.kill"), []byte("1"), 0600); err != nil {
		return fmt.Errorf("kill workload cgroup: %w", err)
	}
	ticker := time.NewTicker(25 * time.Millisecond)
	defer ticker.Stop()
	for {
		populated, err := cgroupPopulated(path)
		if err != nil || !populated {
			return err
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

cancel_hook.text:
type cancelAfterErrContext struct {
	context.Context
	cancel context.CancelFunc
	once   sync.Once
}

func (c *cancelAfterErrContext) Err() error {
	err := c.Context.Err()
	if err == nil {
		c.once.Do(c.cancel)
	}
	return err
}

native_boundary.text:
func validateWorkloadIdentity(identity WorkloadIdentity) error {
	if identity.UID == 0 || identity.GID == 0 {
		return errors.New("native workload requires nonzero UID and GID")
	}
	if os.Geteuid() == int(identity.UID) || os.Getegid() == int(identity.GID) {
		return errors.New("native workload identity must differ from supervisor")
	}
	if os.Geteuid() != 0 {
		return fmt.Errorf("native supervisor requires root to drop workload identity: %w", os.ErrPermission)
	}
	return requireNativeSupervisorKillCapability()
}

// Linux checks the dying parent's signal permission when delivering
// PR_SET_PDEATHSIG. Root without CAP_KILL cannot signal a different tenant UID.
func requireNativeSupervisorKillCapability() error {
	var capabilities [2]unix.CapUserData
	header := unix.CapUserHeader{Version: unix.LINUX_CAPABILITY_VERSION_3}
	if err := unix.Capget(&header, &capabilities[0]); err != nil {
		return fmt.Errorf("inspect native supervisor capabilities: %w", err)
	}
	mask := uint32(1 << unix.CAP_KILL)
	if capabilities[0].Effective&mask == 0 || capabilities[0].Permitted&mask == 0 {
		return fmt.Errorf("native supervisor requires effective and permitted CAP_KILL for tenant parent-death signal: %w", os.ErrPermission)
	}
	bounded, err := unix.PrctlRetInt(unix.PR_CAPBSET_READ, unix.CAP_KILL, 0, 0, 0)
	if err != nil {
		return fmt.Errorf("inspect native supervisor CAP_KILL bound: %w", err)
	}
	if bounded != 1 {
		return fmt.Errorf("native supervisor requires bounded CAP_KILL for tenant parent-death signal: %w", os.ErrPermission)
	}
	return nil
}

func validatePrivateStateRoot(root string) error {
	info, err := os.Lstat(root)
	if err != nil {
		return err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || info.Mode().Perm()&0077 != 0 || owner.Uid != uint32(os.Geteuid()) {
		return errors.New("native state root must be a private supervisor-owned directory")
	}
	return nil
}

func validateTenantExecutable(path string, identity WorkloadIdentity) error {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return errors.New("native executable path must be absolute and clean")
	}
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || owner.Uid != 0 || owner.Gid != identity.GID || info.Mode().Perm()&0010 == 0 || info.Mode().Perm()&0022 != 0 {
		return errors.New("native executable must be root-owned, tenant-group executable, and unwritable by tenants")
	}
	for directory := filepath.Dir(path); ; directory = filepath.Dir(directory) {
		info, err := os.Lstat(directory)
		if err != nil {
			return err
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		mode := info.Mode().Perm()
		if !ok || !info.IsDir() {
			return fmt.Errorf("native executable parent %s is not a directory", directory)
		}
		writableByTenant := mode&0022 != 0 && (info.Mode()&os.ModeSticky == 0 || owner.Uid != 0)
		if owner.Uid != 0 || writableByTenant || mode&0001 == 0 && (owner.Gid != identity.GID || mode&0010 == 0) {
			return fmt.Errorf("native executable parent %s is not safely traversable by tenant", directory)
		}
		if directory == "/" {
			break
		}
	}
	return nil
}

// The supervisor runs in systemd's subgroup, leaving its delegated service
// cgroup process-free so domain controllers can be enabled for sibling roles.
func nativeCgroupRoot(stateRoot string) (string, error) {
	var filesystem syscall.Statfs_t
	if err := syscall.Statfs("/sys/fs/cgroup", &filesystem); err != nil {
		return "", fmt.Errorf("inspect cgroup mount: %w", err)
	}
	if filesystem.Type != cgroup2SuperMagic {
		return "", errors.New("native runtime requires unified cgroup v2")
	}
	data, err := os.ReadFile("/proc/self/cgroup")
	if err != nil {
		return "", fmt.Errorf("read supervisor cgroup: %w", err)
	}
	var membership string
	for line := range strings.SplitSeq(strings.TrimSpace(string(data)), "\n") {
		path, ok := strings.CutPrefix(line, "0::")
		if !ok {
			continue
		}
		if membership != "" {
			return "", errors.New("native runtime has multiple unified cgroup memberships")
		}
		membership = path
	}
	if membership == "" {
		return "", errors.New("native runtime cannot identify its delegated service cgroup")
	}
	parent, err := nativeDelegatedServiceRoot(membership)
	if err != nil {
		return "", err
	}
	if err := requireEmptyCgroup(parent); err != nil {
		return "", fmt.Errorf("native service cgroup must be process-free: %w", err)
	}
	controllers, err := os.ReadFile(filepath.Join(parent, "cgroup.controllers"))
	if err != nil {
		return "", fmt.Errorf("read delegated service controllers: %w", err)
	}
	for _, controller := range []string{"memory", "cpu", "io"} {
		if !slices.Contains(strings.Fields(string(controllers)), controller) {
			return "", fmt.Errorf("native service cgroup lacks delegated %s controller", controller)
		}
	}
	return filepath.Join(parent, nativeCgroupName(stateRoot)), nil
}

func nativeDelegatedServiceRoot(membership string) (string, error) {
	if !filepath.IsAbs(membership) || filepath.Clean(membership) != membership {
		return "", errNativeSubgroupRequired
	}
	service, ok := strings.CutSuffix(membership, "/supervisor")
	if !ok || service == "" || service == "/" || !strings.HasSuffix(filepath.Base(service), ".service") {
		return "", errNativeSubgroupRequired
	}
	return filepath.Join("/sys/fs/cgroup", service), nil
}

func requireEmptyCgroup(path string) error {
	procs, err := os.ReadFile(filepath.Join(path, "cgroup.procs"))
	if err != nil {
		return err
	}
	if strings.TrimSpace(string(procs)) != "" {
		return errors.New("cgroup contains processes")
	}
	return nil
}

func prepareNativeCgroupRoot(root string) error {
	parent := filepath.Dir(root)
	if err := requireEmptyCgroup(parent); err != nil {
		return fmt.Errorf("native service cgroup must stay process-free: %w", err)
	}
	if err := enableCgroupMemoryController(parent); err != nil {
		return fmt.Errorf("enable native service memory controller: %w", err)
	}
	if err := enableCgroupCPUController(parent); err != nil {
		return fmt.Errorf("enable native service CPU controller: %w", err)
	}
	if err := enableCgroupIOController(parent); err != nil {
		return fmt.Errorf("enable native service I/O controller: %w", err)
	}
	if err := os.MkdirAll(root, 0700); err != nil {
		return fmt.Errorf("create native runner cgroup: %w", err)
	}
	if err := requireEmptyCgroup(root); err != nil {
		return fmt.Errorf("native runner cgroup must be process-free: %w", err)
	}
	if err := enableCgroupMemoryController(root); err != nil {
		return fmt.Errorf("enable native runner memory controller: %w", err)
	}
	if err := enableCgroupCPUController(root); err != nil {
		return fmt.Errorf("enable native runner CPU controller: %w", err)
	}
	if err := enableCgroupIOController(root); err != nil {
		return fmt.Errorf("enable native runner I/O controller: %w", err)
	}
	if err := configureNativeSiblingResources(parent, root); err != nil {
		return err
	}
	quota, err := deriveNativeWorkloadCPUQuota(parent)
	if err != nil {
		return err
	}
	return setNativeCPUMax(filepath.Join(root, "cpu.max"), quota)
}

// The service unit's memory protection is an ancestor budget. Assign its
// exact configured amount to the supervisor subgroup, never to a workload.
// CPU weights reserve scheduling share under contention without throttling an
// otherwise idle host's database process.
func configureNativeSiblingResources(serviceRoot, runnerRoot string) error {
	supervisor := filepath.Join(serviceRoot, "supervisor")
	if err := requireNativeSupervisorSubgroup(supervisor); err != nil {
		return err
	}
	for _, name := range []string{"memory.min", "memory.low"} {
		value, err := readNativeResourceValue(filepath.Join(serviceRoot, name))
		if err != nil {
			return fmt.Errorf("read native service %s: %w", name, err)
		}
		if err := setNativeResourceValue(filepath.Join(supervisor, name), value); err != nil {
			return fmt.Errorf("reserve native supervisor %s: %w", name, err)
		}
		if err := setNativeResourceValue(filepath.Join(runnerRoot, name), 0); err != nil {
			return fmt.Errorf("remove native runner %s protection: %w", name, err)
		}
	}
	if err := setNativeResourceValue(filepath.Join(supervisor, "cpu.weight"), nativeSupervisorCPUWeight); err != nil {
		return fmt.Errorf("weight native supervisor CPU: %w", err)
	}
	if err := setNativeResourceValue(filepath.Join(runnerRoot, "cpu.weight"), nativeWorkloadCPUWeight); err != nil {
		return fmt.Errorf("weight native runner CPU: %w", err)
	}
	if err := setNativeIOWeight(filepath.Join(supervisor, "io.weight"), nativeSupervisorCPUWeight); err != nil {
		return fmt.Errorf("weight native supervisor I/O: %w", err)
	}
	if err := setNativeIOWeight(filepath.Join(runnerRoot, "io.weight"), nativeWorkloadCPUWeight); err != nil {
		return fmt.Errorf("weight native runner I/O: %w", err)
	}
	if err := setNativeSupervisorOOMPreference(supervisor); err != nil {
		return fmt.Errorf("protect native supervisor from systemd-oomd: %w", err)
	}
	if err := clearNativeWorkloadOOMPreference(runnerRoot); err != nil {
		return fmt.Errorf("keep native runner eligible for systemd-oomd: %w", err)
	}
	return nil
}

func requireNativeSupervisorSubgroup(path string) error {
	info, err := os.Lstat(path)
	if err != nil {
		return fmt.Errorf("inspect native supervisor subgroup: %w", err)
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || owner.Uid != 0 {
		return errors.New("native supervisor subgroup must be a root-owned direct directory")
	}
	return nil
}

func configureNativeRoleResources(path string, quota uint64) error {
	for _, name := range []string{"memory.min", "memory.low"} {
		if err := setNativeResourceValue(filepath.Join(path, name), 0); err != nil {
			return fmt.Errorf("remove native workload %s protection: %w", name, err)
		}
	}
	if err := setNativeResourceValue(filepath.Join(path, "cpu.weight"), nativeWorkloadCPUWeight); err != nil {
		return fmt.Errorf("weight native workload CPU: %w", err)
	}
	if err := setNativeIOWeight(filepath.Join(path, "io.weight"), nativeWorkloadCPUWeight); err != nil {
		return fmt.Errorf("weight native workload I/O: %w", err)
	}
	if err := clearNativeWorkloadOOMPreference(path); err != nil {
		return fmt.Errorf("keep native workload eligible for systemd-oomd: %w", err)
	}
	return setNativeCPUMax(filepath.Join(path, "cpu.max"), quota)

native_resources.text:
func deriveNativeWorkloadCPUQuota(serviceRoot string) (uint64, error) {
	var affinity unix.CPUSet
	if err := unix.SchedGetaffinity(0, &affinity); err != nil {
		return 0, fmt.Errorf("read native supervisor CPU affinity: %w", err)
	}
	return deriveNativeWorkloadCPUQuotaAt("/sys/fs/cgroup", serviceRoot, affinity.Count())
}

func deriveNativeWorkloadCPUQuotaAt(mountRoot, serviceRoot string, availableCPUs int) (uint64, error) {
	if availableCPUs <= 0 || availableCPUs > 1024 || !strings.HasPrefix(serviceRoot, mountRoot+string(filepath.Separator)) {
		return 0, errors.New("native CPU quota has invalid cgroup root or affinity")
	}
	available := uint64(availableCPUs) * nativeCPUPeriod
	for ancestor := serviceRoot; ancestor != mountRoot; ancestor = filepath.Dir(ancestor) {
		data, err := os.ReadFile(filepath.Join(ancestor, "cpu.max"))
		if err != nil {
			return 0, fmt.Errorf("read native ancestor CPU cap: %w", err)
		}
		fields := strings.Fields(string(data))
		if len(fields) != 2 {
			return 0, errors.New("native ancestor CPU cap is malformed")
		}
		period, err := strconv.ParseUint(fields[1], 10, 64)
		if err != nil || period < 1000 || period > 1000000 {
			return 0, errors.New("native ancestor CPU period is malformed")
		}
		if fields[0] != "max" {
			quota, err := strconv.ParseUint(fields[0], 10, 64)
			if err != nil || quota == 0 {
				return 0, errors.New("native ancestor CPU quota is malformed")
			}
			// Quotas greater than CPU affinity cannot narrow the effective cap.
			// This comparison also bounds multiplication in the next branch.
			if quota < uint64(availableCPUs)*period {
				available = min(available, quota*nativeCPUPeriod/period)
			}
		}
	}
	// Bound the aggregate runner and each role to 75% of the effective
	// ancestor/affinity budget. The remaining quarter is left for the manager.
	quota := available * 3 / 4
	if quota < 1000 || quota >= available {
		return 0, errors.New("native CPU budget leaves no safe supervisor headroom")
	}
	return quota, nil
}

func setNativeCPUMax(path string, quota uint64) error {
	if quota < 1000 {
		return errors.New("native CPU cap is below the kernel minimum")
	}
	want := strconv.FormatUint(quota, 10) + " " + strconv.FormatUint(nativeCPUPeriod, 10)
	if err := os.WriteFile(path, []byte(want), 0600); err != nil {
		return err
	}
	readback, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if strings.Join(strings.Fields(string(readback)), " ") != want {
		return errors.New("native CPU cap readback differs from requested value")
	}
	return nil
}

native_permissions.text:
func configureTenantCgroupDirectory(path string, identity WorkloadIdentity) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || owner.Uid != 0 {
		return fmt.Errorf("native cgroup %s must be a root-owned directory", path)
	}
	if err := os.Chmod(path, 0700); err != nil {
		return fmt.Errorf("seal native cgroup %s before assigning workload group: %w", path, err)
	}
	if err := os.Chown(path, 0, int(identity.GID)); err != nil {
		return fmt.Errorf("assign native cgroup %s to workload group: %w", path, err)
	}
	if err := os.Chmod(path, 0710); err != nil {
		return fmt.Errorf("set native cgroup %s traversal mode: %w", path, err)
	}
	info, err = os.Lstat(path)
	if err != nil {
		return err
	}
	owner, ok = info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 ||
		owner.Uid != 0 || owner.Gid != identity.GID || info.Mode().Perm() != 0710 {
		return fmt.Errorf("native cgroup %s did not retain root-owned workload-group traversal", path)
	}
	return nil
}

func tenantCgroupMode(info os.FileInfo, identity WorkloadIdentity) (uint32, error) {
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		return 0, errors.New("cannot inspect native cgroup ownership")
	}
	permissions := uint32(info.Mode().Perm())
	switch {
	case owner.Uid == identity.UID:
		return permissions >> 6 & 7, nil
	case owner.Gid == identity.GID:
		return permissions >> 3 & 7, nil
	default:
		return permissions & 7, nil
	}
}

// The workload has no supplementary groups or capabilities, so these mode
// checks match the credentials it will use after the native helper drops root.
func validateTenantCgroupTraversal(path string, identity WorkloadIdentity) error {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return errors.New("native cgroup path must be absolute and clean")
	}
	for directory := path; ; directory = filepath.Dir(directory) {
		info, err := os.Lstat(directory)
		if err != nil {
			return fmt.Errorf("inspect native cgroup ancestor %s: %w", directory, err)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("native cgroup ancestor %s is not a directory", directory)
		}
		mode, err := tenantCgroupMode(info, identity)
		if err != nil {
			return fmt.Errorf("inspect native cgroup ancestor %s: %w", directory, err)
		}
		if mode&1 == 0 || mode&2 != 0 {
			return fmt.Errorf("workload cannot safely traverse native cgroup ancestor %s", directory)
		}
		if directory == "/" {
			return nil
		}
	}
}

func validateTenantCgroupAccounting(rolePath string, identity WorkloadIdentity) error {
	if err := validateTenantCgroupTraversal(rolePath, identity); err != nil {
		return err
	}
	for _, name := range []string{"memory.current", "memory.max"} {
		path := filepath.Join(rolePath, name)
		info, err := os.Lstat(path)
		if err != nil {
			return fmt.Errorf("inspect workload memory accounting %s: %w", path, err)
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok || !info.Mode().IsRegular() || owner.Uid != 0 {
			return fmt.Errorf("workload memory accounting %s is not a root-owned file", path)
		}
		mode, err := tenantCgroupMode(info, identity)
		if err != nil {
			return fmt.Errorf("inspect workload memory accounting %s: %w", path, err)
		}
		if mode&4 == 0 || mode&2 != 0 {
			return fmt.Errorf("workload cannot safely read memory accounting %s", path)
		}
	}
	for _, path := range []string{
		filepath.Join(filepath.Dir(rolePath), "cgroup.subtree_control"),
		filepath.Join(rolePath, "cgroup.procs"),
	} {
		if err := validateTenantCgroupControl(path, identity); err != nil {
			return err
		}
	}
	return nil
}

func validateTenantCgroupControl(path string, identity WorkloadIdentity) error {
	info, err := os.Lstat(path)
	if err != nil {
		return fmt.Errorf("inspect native cgroup control %s: %w", path, err)
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || owner.Uid != 0 {
		return fmt.Errorf("native cgroup control %s is not a root-owned file", path)
	}
	mode, err := tenantCgroupMode(info, identity)
	if err != nil {
		return fmt.Errorf("inspect native cgroup control %s: %w", path, err)
	}
	if mode&2 != 0 {
		return fmt.Errorf("workload can write native cgroup control %s", path)
	}
	return nil
}

native_launch.text:
// Starts a same-binary helper through clone3(CLONE_INTO_CGROUP), then waits
// until it has successfully execed the target. The returned command PID is the
// target PID because the helper uses execve rather than spawning again.
func launchNativeWorkload(ctx context.Context, target *exec.Cmd, cgroup *os.File, cgroupPath string, identity WorkloadIdentity) (*exec.Cmd, func(), <-chan error, error) {
	if !filepath.IsAbs(cgroupPath) || filepath.Clean(cgroupPath) != cgroupPath {
		return nil, nil, nil, errors.New("native launch requires an absolute cgroup path")
	}
	if err := validateNativeTargetExtraFileCount(len(target.ExtraFiles)); err != nil {
		return nil, nil, nil, err
	}
	if err := requireNativeSupervisorKillCapability(); err != nil {
		return nil, nil, nil, err
	}
	request := nativeExecRequest{Path: target.Path, Args: target.Args, Env: target.Env, Identity: identity, ParentPID: os.Getpid(), ExtraFileCount: new(len(target.ExtraFiles))}
	data, err := json.Marshal(request)
	if err != nil || len(data) > 128<<10 {
		return nil, nil, nil, errors.New("native helper request too large")
	}
	requestRead, requestWrite, err := os.Pipe()
	if err != nil {
		return nil, nil, nil, err
	}
	defer requestRead.Close()
	defer requestWrite.Close()
	statusRead, statusWrite, err := os.Pipe()
	if err != nil {
		return nil, nil, nil, err
	}
	defer statusRead.Close()
	defer statusWrite.Close()
	helper := exec.Command("/proc/self/exe", workloadHelperArgument)
	helper.Env = []string{}
	helper.Stdout, helper.Stderr = target.Stdout, target.Stderr
	helper.ExtraFiles = append([]*os.File{requestRead, statusWrite}, target.ExtraFiles...)
	helper.SysProcAttr = &syscall.SysProcAttr{Setpgid: true, Pdeathsig: syscall.SIGKILL, UseCgroupFD: true, CgroupFD: int(cgroup.Fd())}
	release, waited, err := startWorkloadOnLockedThreadWithCheck(helper, requireNativeSupervisorKillCapability)
	if err != nil {
		return nil, nil, nil, err
	}
	fail := func(cause error) (*exec.Cmd, func(), <-chan error, error) {
		_ = helper.Process.Kill()
		release()
		<-waited
		return nil, nil, nil, cause
	}
	_ = requestRead.Close()
	_ = statusWrite.Close()
	deadline := time.Now().Add(10 * time.Second)
	if due, ok := ctx.Deadline(); ok && due.Before(deadline) {
		deadline = due
	}
	_ = requestWrite.SetWriteDeadline(deadline)
	_ = statusRead.SetReadDeadline(deadline)
	stop := context.AfterFunc(ctx, func() { _ = requestWrite.Close(); _ = statusRead.Close() })
	defer stop()
	if _, err := requestWrite.Write(data); err != nil {
		return fail(fmt.Errorf("send native helper request: %w", err))
	}
	if err := requestWrite.Close(); err != nil {
		return fail(fmt.Errorf("close native helper request: %w", err))
	}
	status, err := io.ReadAll(io.LimitReader(statusRead, 4096))
	if err != nil {
		if ctx.Err() != nil {
			return fail(ctx.Err())
		}
		return fail(fmt.Errorf("native helper exec status: %w", err))
	}
	if len(status) != 0 {
		return fail(fmt.Errorf("native helper failed before target exec: %s", status))
	}
	if err := ctx.Err(); err != nil {
		return fail(err)
	}
	if err := verifyNativeExec(helper.Process.Pid, cgroupPath, identity); err != nil {
		return fail(err)
	}
	return helper, release, waited, nil
}

// Pipe EOF alone also occurs if the helper dies before exec. Inspect the live
// PID after EOF before admitting a role; a zombie still has a /proc stat entry.
func verifyNativeExec(pid int, cgroupPath string, identity WorkloadIdentity) error {
	stat, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
	if err != nil {
		return fmt.Errorf("native target exited before verification: %w", err)
	}
	if err := verifyNativeExecNice(stat); err != nil {
		return err
	}
	oomScore, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "oom_score_adj"))
	if err != nil {
		return fmt.Errorf("inspect native target OOM score adjustment: %w", err)
	}
	adjustment, err := strconv.Atoi(strings.TrimSpace(string(oomScore)))
	if err != nil || adjustment < 0 {
		return errors.New("native target retained protected supervisor OOM score adjustment")
	}
	ioPriority, err := readNativeIOPriority(pid)
	if err != nil {
		return fmt.Errorf("inspect native target I/O priority: %w", err)
	}
	if ioPriority != 0 && (ioPriority>>13 != 2 || ioPriority&((1<<13)-1) < 4) && ioPriority>>13 != 3 {
		return errors.New("native target retained protected supervisor I/O priority")
	}
	cmdline, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "cmdline"))
	if err != nil || len(cmdline) == 0 || bytes.Contains(cmdline, []byte(workloadHelperArgument)) {
		return errors.New("native helper did not exec the target")
	}
	if err := probeNativeTargetIdentity(pid, identity); err != nil {
		return err
	}
	contained, err := nativeCgroupContainsPID(cgroupPath, pid)
	if err != nil {
		return err
	}
	if !contained {
		return errors.New("native target escaped its role cgroup")
	}
	return nil

native_privilege.text:
func init() {
	if len(os.Args) == 2 && os.Args[1] == workloadHelperArgument {
		runNativeWorkloadHelper()
	}
}

// The helper is part of the same binary. It is the only root userspace code
// launched into a role cgroup; it must drop all privilege before execing the
// artifact. Its status FD closes on successful exec and reports pre-exec errors.
func runNativeWorkloadHelper() {
	// prctl, credential changes, and exec must affect the same Linux task.
	// A Go scheduler migration here would silently undo the security boundary.
	runtime.LockOSThread()
	status := os.NewFile(4, "native-exec-status")
	fail := func(err error) {
		if status != nil {
			_, _ = io.WriteString(status, err.Error())
		}
		os.Exit(113)
	}
	requestFile := os.NewFile(3, "native-exec-request")
	if requestFile == nil || status == nil {
		fail(errors.New("native helper missing protocol files"))
	}
	data, err := io.ReadAll(io.LimitReader(requestFile, 128<<10+1))
	if err != nil || len(data) > 128<<10 {
		fail(errors.New("native helper request invalid"))
	}
	_ = requestFile.Close()
	var request nativeExecRequest
	if err := json.Unmarshal(data, &request); err != nil || !validNativeExecRequest(request) {
		fail(errors.New("native helper request malformed"))
	}
	// Move the status FD above target ExtraFiles before installing target FD 3.
	statusFD, err := unix.FcntlInt(status.Fd(), unix.F_DUPFD_CLOEXEC, 10)
	if err != nil {
		fail(fmt.Errorf("native helper status fd: %w", err))
	}
	_ = status.Close()
	status = os.NewFile(uintptr(statusFD), "native-exec-status")
	if err := remapNativeTargetExtraFiles(*request.ExtraFileCount); err != nil {
		fail(err)
	}
	if err := dropNativePrivileges(request.Identity, request.ParentPID); err != nil {
		fail(err)
	}
	if err := syscall.Exec(request.Path, request.Args, request.Env); err != nil {
		fail(fmt.Errorf("exec native workload: %w", err))
	}
}

func validNativeExecRequest(request nativeExecRequest) bool {
	return request.Path != "" && len(request.Args) != 0 && request.ParentPID >= 2 &&
		request.Identity.UID != 0 && request.Identity.GID != 0 && request.ExtraFileCount != nil &&
		validateNativeTargetExtraFileCount(*request.ExtraFileCount) == nil
}

func validateNativeTargetExtraFileCount(count int) error {
	if count < 0 || count > maxNativeTargetExtraFiles {
		return errors.New("native target supports at most one inherited file")
	}
	return nil
}

// The helper's FDs 3 and 4 carry the request and status pipes. os/exec places
// the only optional target file at FD 5. A zero-file launch must leave FD 5
// alone: the Go runtime can allocate its epoll descriptor there during init.
func remapNativeTargetExtraFiles(count int) error {
	if err := validateNativeTargetExtraFileCount(count); err != nil {
		return err
	}
	if count == 0 {
		return nil
	}
	if _, err := unix.FcntlInt(5, unix.F_GETFD, 0); err != nil {
		return fmt.Errorf("native helper missing inherited target fd 5: %w", err)
	}
	if err := unix.Dup3(5, 3, 0); err != nil {
		return fmt.Errorf("native helper target fd 3: %w", err)
	}
	if err := unix.Close(5); err != nil {
		return fmt.Errorf("close native helper inherited target fd 5: %w", err)
	}
	return nil
}

func dropNativePrivileges(identity WorkloadIdentity, parentPID int) error {
	if os.Geteuid() != 0 || identity.UID == 0 || identity.GID == 0 {
		return errors.New("native helper requires root and nonzero workload identity")
	}
	// The helper inherits the protected supervisor's scheduling attributes.
	// Reset them while root before the irreversible UID and capability drop.
	if err := unix.Setpriority(unix.PRIO_PROCESS, 0, 0); err != nil {
		return fmt.Errorf("reset native workload nice: %w", err)
	}
	if err := resetNativeWorkloadOOMScore("/proc/self/oom_score_adj"); err != nil {
		return err
	}
	if err := setNativeIOPriority(0, nativeIOPriorityNeutral); err != nil {
		return fmt.Errorf("reset native workload I/O priority: %w", err)
	}
	if err := unix.Prctl(unix.PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0); err != nil {
		return fmt.Errorf("set native no_new_privs: %w", err)
	}
	if err := unix.Prctl(unix.PR_CAP_AMBIENT, unix.PR_CAP_AMBIENT_CLEAR_ALL, 0, 0, 0); err != nil {
		return fmt.Errorf("clear native ambient caps: %w", err)
	}
	data, err := os.ReadFile("/proc/sys/kernel/cap_last_cap")
	if err != nil {
		return fmt.Errorf("read native cap bound: %w", err)
	}
	last, err := strconv.Atoi(strings.TrimSpace(string(data)))
	if err != nil || last < 0 || last > 255 {
		return errors.New("invalid native cap bound")
	}
	for capability := range last + 1 {
		if err := unix.Prctl(unix.PR_CAPBSET_DROP, uintptr(capability), 0, 0, 0); err != nil {
			return fmt.Errorf("drop native bounding capability %d: %w", capability, err)
		}
	}
	var inherited [2]unix.CapUserData
	inheritedHeader := unix.CapUserHeader{Version: unix.LINUX_CAPABILITY_VERSION_3}
	if err := unix.Capget(&inheritedHeader, &inherited[0]); err != nil {
		return fmt.Errorf("inspect native inheritable capabilities: %w", err)
	}
	for index := range inherited {
		inherited[index].Inheritable = 0
	}
	if err := unix.Capset(&inheritedHeader, &inherited[0]); err != nil {
		return fmt.Errorf("clear native inheritable capabilities: %w", err)
	}
	if err := unix.Setgroups(nil); err != nil {
		return fmt.Errorf("clear native supplementary groups: %w", err)
	}
	if err := unix.Setresgid(int(identity.GID), int(identity.GID), int(identity.GID)); err != nil {
		return fmt.Errorf("drop native group: %w", err)
	}
	if err := unix.Setresuid(int(identity.UID), int(identity.UID), int(identity.UID)); err != nil {
		return fmt.Errorf("drop native user: %w", err)
	}
	// Credential transitions clear Pdeathsig. Rearm it and check for a parent
	// death between clone3 and this point before allowing target exec.
	if err := unix.Prctl(unix.PR_SET_PDEATHSIG, uintptr(syscall.SIGKILL), 0, 0, 0); err != nil {
		return fmt.Errorf("rearm native parent death: %w", err)
	}
	if os.Getppid() != parentPID {
		return errors.New("native supervisor died before workload exec")
	}
	var caps [2]unix.CapUserData
	header := unix.CapUserHeader{Version: unix.LINUX_CAPABILITY_VERSION_3}
	if err := unix.Capget(&header, &caps[0]); err != nil {
		return fmt.Errorf("verify native capabilities: %w", err)
	}
	for _, capset := range caps {
		if capset.Effective != 0 || capset.Permitted != 0 || capset.Inheritable != 0 {
			return errors.New("native workload retained capabilities")
		}
	}
	return nil
}

native_identity.text:
func probeNativeTargetIdentity(pid int, identity WorkloadIdentity) error {
	data, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "status"))
	if err != nil {
		return fmt.Errorf("read native probe target status: %w", err)
	}
	wantedUID := strconv.FormatUint(uint64(identity.UID), 10)
	wantedGID := strconv.FormatUint(uint64(identity.GID), 10)
	checks := map[string]func([]string) bool{
		"Uid:": func(values []string) bool {
			return len(values) == 4 && values[0] == wantedUID && values[1] == wantedUID && values[2] == wantedUID && values[3] == wantedUID
		},
		"Gid:": func(values []string) bool {
			return len(values) == 4 && values[0] == wantedGID && values[1] == wantedGID && values[2] == wantedGID && values[3] == wantedGID
		},
		"Groups:":     func(values []string) bool { return len(values) == 0 },
		"CapInh:":     func(values []string) bool { return len(values) == 1 && values[0] == "0000000000000000" },
		"CapPrm:":     func(values []string) bool { return len(values) == 1 && values[0] == "0000000000000000" },
		"CapEff:":     func(values []string) bool { return len(values) == 1 && values[0] == "0000000000000000" },
		"CapBnd:":     func(values []string) bool { return len(values) == 1 && values[0] == "0000000000000000" },
		"CapAmb:":     func(values []string) bool { return len(values) == 1 && values[0] == "0000000000000000" },
		"NoNewPrivs:": func(values []string) bool { return len(values) == 1 && values[0] == "1" },
	}
	seen := make(map[string]bool, len(checks))
	for line := range strings.SplitSeq(string(data), "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		check, ok := checks[fields[0]]
		if ok {
			if !check(fields[1:]) {
				return fmt.Errorf("native probe target has unsafe %s status", fields[0])
			}
			seen[fields[0]] = true
		}
	}
	if len(seen) != len(checks) {
		return errors.New("native probe target status lacks credential or privilege proof")
	}
	return nil
}

native_membership.text:
func nativeCgroupContainsPID(path string, pid int) (bool, error) {
	data, err := os.ReadFile(filepath.Join(path, "cgroup.procs"))
	if err != nil {
		return false, fmt.Errorf("read native cgroup membership: %w", err)
	}
	want := strconv.Itoa(pid)
	for field := range strings.FieldsSeq(string(data)) {
		if field == want {
			return true, nil
		}
	}
	return false, nil
}

locked_launch.text:
// Linux delivers Pdeathsig when the thread that created the child exits.
// Keep that thread alive until Wait so an idle Go thread cannot kill a live workload.
func startWorkloadOnLockedThread(cmd *exec.Cmd) (func(), <-chan error, error) {
	return startWorkloadOnLockedThreadWithCheck(cmd, nil)
}

func startWorkloadOnLockedThreadWithCheck(cmd *exec.Cmd, check func() error) (func(), <-chan error, error) {
	started := make(chan error, 1)
	release := make(chan struct{})
	waited := make(chan error, 1)
	go func() {
		runtime.LockOSThread()
		defer runtime.UnlockOSThread()
		if check != nil {
			if err := check(); err != nil {
				started <- err
				return
			}
		}
		err := cmd.Start()
		started <- err
		if err != nil {
			return
		}
		<-release
		waited <- cmd.Wait()
	}()
	if err := <-started; err != nil {
		return nil, nil, err
	}
	return sync.OnceFunc(func() { close(release) }), waited, nil
}

runner_drain.text:
func (p *processRunner) drain(ctx context.Context, record processRecord) {
	if p.signalRecorded(ctx, record, unix.SIGTERM) != nil {
		return
	}
	ctx, cancel := context.WithTimeout(ctx, time.Duration(record.DrainMillis)*time.Millisecond)
	defer cancel()
	ticker := time.NewTicker(25 * time.Millisecond)
	defer ticker.Stop()
	for {
		if populated, err := cgroupPopulated(filepath.Join(p.cgroups, record.Role)); err != nil || !populated {
			return
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

func (p *processRunner) signalRecorded(ctx context.Context, record processRecord, signal unix.Signal) error {
	role := record.Role
	if record.PID < 2 || !nativeProcessAliveWithStart(record.PID, record.StartTime) {
		return errors.New("recorded native process is unavailable")
	}
	fd, err := unix.PidfdOpen(record.PID, 0)
	if err != nil {
		return err
	}
	defer unix.Close(fd)
	populated, err := cgroupPopulated(filepath.Join(p.cgroups, role))
	if err != nil || !populated || !nativeProcessAliveWithStart(record.PID, record.StartTime) {
		return errors.New("recorded native process changed before reload")
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	return unix.PidfdSendSignal(fd, signal, nil, 0)
}

process_readback.text:
func processRunningWithStart(pid int, start string) bool {
	if start == "" || currentStartTime(pid) != start {
		return false
	}
	data, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
	if err != nil {
		return false
	}
	closing := strings.LastIndexByte(string(data), ')')
	if closing < 0 {
		return false
	}
	fields := strings.Fields(string(data[closing+1:]))
	return len(fields) > 0 && fields[0] != "Z" && fields[0] != "X"
}
